SELECT i_brand, ca_city, avg_sales_price, total_quantity, CASE WHEN avg_sales_price >= 200 THEN 'Premium' WHEN avg_sales_price >= 100 THEN 'Midrange' ELSE 'Budget' END AS price_tier, ROW_NUMBER() OVER (PARTITION BY i_brand ORDER BY avg_sales_price DESC) AS city_rank, LAG(avg_sales_price) OVER (PARTITION BY i_brand ORDER BY avg_sales_price DESC) AS prev_avg_price, avg_sales_price - LAG(avg_sales_price) OVER (PARTITION BY i_brand ORDER BY avg_sales_price DESC) AS price_diff FROM ( SELECT i.i_brand, ca.ca_city, AVG(ws.ws_sales_price) AS avg_sales_price, SUM(ws.ws_quantity) AS total_quantity FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk JOIN customer_address ca ON ws.ws_bill_addr_sk = ca.ca_address_sk GROUP BY i.i_brand, ca.ca_city ) agg WHERE total_quantity > 500 ORDER BY i_brand, city_rank
